solution:
fn stats[T](data: &Vec[T]) -> (T, T, T)
  where T: Ord + Clone + Display + Default,
{
  var min = data[0].clone();
  var max = data[0].clone();
  for item in data {
    if item < min { min = item.clone(); }
    if item > max { max = item.clone(); }
  }
  return (min, max, T::default());
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(5); v.push(3); v.push(7); v.push(2);
  let (min, _, _) = stats[Int](&v);
  return min;
}
